},from_date:function(frm){
        ["journal_entries", "account_summary"].forEach(f=>{frm.clear_table(f);frm.refresh_field(f);});
},to_date:function(frm){
        ["journal_entries", "account_summary"].forEach(f=>{frm.clear_table(f);frm.refresh_field(f);});
}});

})();

